settings.custom_css:
selector .ak-bar-item .elementor-icon { display: block; line-height: 1; }
@media (max-width: 1024px) {
  selector .ak-bar-item { border-bottom: 1px solid #D4D8DF; }
  selector .ak-bar-item:nth-child(2n) { border-right: 0; }
}
@media (max-width: 767px) {
  /* icono a la izquierda del texto, como el XD móvil */
  selector .ak-bar-item { display: grid !important; grid-template-columns: 30px 1fr; column-gap: 10px; align-items: center; }
  selector .ak-bar-item > .elementor-widget-icon { grid-row: 1 / 3; }
}
